<?php require_once __DIR__.'/lib/auth.php';startAppSession();$token=$_GET['token']??$_POST['token']??'';$error='';$notice='';$hash=hash('sha256',$token);$s=db()->prepare('SELECT pr.id,pr.user_id FROM password_reset_tokens pr WHERE pr.token_hash=? AND pr.used_at IS NULL AND pr.expires_at>NOW() LIMIT 1');$s->execute([$hash]);$reset=$s->fetch();if(!$reset)$error='This reset link is invalid or expired.';if($_SERVER['REQUEST_METHOD']==='POST'&&$reset&&verifyCsrf($_POST['csrf']??'')){try{$password=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';if(strlen($password)<8||$password!==$confirm)throw new RuntimeException('Passwords must match and contain at least 8 characters.');db()->beginTransaction();db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$reset['user_id']]);db()->prepare('UPDATE password_reset_tokens SET used_at=NOW() WHERE id=?')->execute([$reset['id']]);db()->commit();header('Location: login.php?reset=1');exit;}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error=$e->getMessage();}}$mode='reset';require __DIR__.'/views/auth.php';
